struct TlCtor {
	uint32_t cid = 0;
	uint32_t nameOff = 0;
	uint16_t fstart = 0;
	uint8_t fcount = 0;
	uint8_t isFunc = 0;
};

struct TlField {
	uint32_t nameOff = 0;
	uint16_t targetIdx = 0;
	uint8_t kind = 0;
	uint8_t elemKind = 0;
	int8_t flagSlot = -1;
	uint8_t flagBit = 0;
};

struct TlSchemaData {
	bool ready = false;
	QByteArray pool;
	std::vector<TlCtor> ctors;
	std::vector<TlField> fields;
	uint32_t helpGetNearestDcCid = 0;
};

const TlSchemaData &GetTlSchema() {
	static TlSchemaData schema;
	static std::once_flag once;
	std::call_once(once, [] {
		const auto raw = qUncompress(
			kTlSchemaPack,
			int(sizeof(kTlSchemaPack)));
		if (raw.size() < 16 || std::memcmp(raw.constData(), "MTL1", 4) != 0) {
			return;
		}
		const auto *ptr = reinterpret_cast<const uchar*>(raw.constData());
		const auto poolBytes = qFromLittleEndian<quint32>(ptr + 4);
		const auto numCtors = qFromLittleEndian<quint32>(ptr + 8);
		const auto numFields = qFromLittleEndian<quint32>(ptr + 12);
		const auto expected = quint64(16)
			+ quint64(poolBytes)
			+ quint64(numCtors) * 12ULL
			+ quint64(numFields) * 12ULL;
		if (poolBytes == 0 || quint64(raw.size()) != expected) {
			return;
		}
		schema.pool = raw.mid(16, int(poolBytes));
		if (schema.pool.isEmpty() || schema.pool.back() != '\0') {
			schema.pool.clear();
			return;
		}
		const auto *cptr = ptr + 16 + poolBytes;
		schema.ctors.resize(numCtors);
		for (quint32 i = 0; i < numCtors; ++i) {
			const auto *p = cptr + i * 12;
			schema.ctors[i].cid = qFromLittleEndian<quint32>(p);
			schema.ctors[i].nameOff = qFromLittleEndian<quint32>(p + 4);
			schema.ctors[i].fstart = qFromLittleEndian<quint16>(p + 8);
			schema.ctors[i].fcount = p[10];
			schema.ctors[i].isFunc = p[11];
		}
		const auto *fptr = cptr + quint64(numCtors) * 12ULL;
		schema.fields.resize(numFields);
		for (quint32 i = 0; i < numFields; ++i) {
			const auto *p = fptr + i * 12;
			schema.fields[i].nameOff = qFromLittleEndian<quint32>(p);
			schema.fields[i].targetIdx = qFromLittleEndian<quint16>(p + 4);
			schema.fields[i].kind = p[6];
			schema.fields[i].elemKind = p[7];
			schema.fields[i].flagSlot = static_cast<int8_t>(p[8]);
			schema.fields[i].flagBit = p[9];
		}
		for (const auto &c : schema.ctors) {
			if (c.nameOff < quint32(schema.pool.size())) {
				const auto *name = schema.pool.constData() + c.nameOff;
				if (std::strcmp(name, "help.getNearestDc") == 0) {
					schema.helpGetNearestDcCid = c.cid;
					break;
				}
			}
		}
		schema.ready = true;
	});
	return schema;
}

const char *PoolStr(const TlSchemaData &s, uint32_t off) {
	if (off >= quint32(s.pool.size())) {
		return "";
	}
	return s.pool.constData() + off;
}

int FindCtorIdx(const TlSchemaData &s, uint32_t cid) {
	auto lo = size_t(0);
	auto hi = s.ctors.size();
	while (lo < hi) {
		const auto mid = lo + (hi - lo) / 2;
		if (s.ctors[mid].cid < cid) {
			lo = mid + 1;
		} else {
			hi = mid;
		}
	}
	if (lo < s.ctors.size() && s.ctors[lo].cid == cid) {
		return int(lo);
	}
	return -1;
}

struct TlVal {
	enum class Kind {
		Null,
		Bool,
		Int,
		Double,
		String,
		Bytes,
		Object,
		List,
	};
	Kind kind = Kind::Null;
	bool boolVal = false;
	qint64 intVal = 0;
	QString strVal;
	QString typeName;
	std::vector<std::pair<QString, TlVal>> fields;
	std::vector<TlVal> list;
};

struct TlReader {
	const uchar *data = nullptr;
	int size = 0;
	int pos = 0;

	bool readU32(uint32_t &out) {
		if (pos + 4 > size) {
			return false;
		}
		out = qFromLittleEndian<quint32>(data + pos);
		pos += 4;
		return true;
	}

	bool readS32(qint32 &out) {
		if (pos + 4 > size) {
			return false;
		}
		out = qFromLittleEndian<qint32>(data + pos);
		pos += 4;
		return true;
	}

	bool readS64(qint64 &out) {
		if (pos + 8 > size) {
			return false;
		}
		out = qFromLittleEndian<qint64>(data + pos);
		pos += 8;
		return true;
	}

	bool skip(int n) {
		if (n < 0 || pos + n > size) {
			return false;
		}
		pos += n;
		return true;
	}

	bool readTlBytes(QByteArray &out) {
		if (pos >= size) {
			return false;
		}
		const auto first = data[pos];
		pos += 1;
		int len = 0;
		int head = 1;
		if (first == 254) {
			if (pos + 3 > size) {
				return false;
			}
			len = int(data[pos]) | (int(data[pos + 1]) << 8) | (int(data[pos + 2]) << 16);
			pos += 3;
			head = 4;
		} else {
			len = int(first);
		}
		if (pos + len > size) {
			return false;
		}
		out = QByteArray(reinterpret_cast<const char*>(data + pos), len);
		pos += len;
		const int pad = (4 - ((len + head) & 3)) & 3;
		if (pos + pad > size) {
			return false;
		}
		pos += pad;
		return true;
	}
};

constexpr uint32_t kTlVectorCid = 0x1cb5c415U;
constexpr uint32_t kTlBoolTrue = 0x997275b5U;
constexpr uint32_t kTlBoolFalse = 0xbc799737U;

bool DecodeTlFields(
		const TlSchemaData &s,
		TlReader &r,
		int ctorIdx,
		int depth,
		TlVal &out);

bool DecodeTlObj(
		const TlSchemaData &s,
		TlReader &r,
		int depth,
		TlVal &out);

bool DecodeTlVal(
		const TlSchemaData &s,
		TlReader &r,
		uint8_t kind,
		uint16_t targetIdx,
		int depth,
		TlVal &out) {
	if (depth > 16) {
		return false;
	}
	switch (kind) {
	case 0: {
		qint32 v = 0;
		if (!r.readS32(v)) {
			return false;
		}
		out.kind = TlVal::Kind::Int;
		out.intVal = v;
		return true;
	}
	case 1: {
		qint64 v = 0;
		if (!r.readS64(v)) {
			return false;
		}
		out.kind = TlVal::Kind::Int;
		out.intVal = v;
		return true;
	}
	case 2: {
		if (!r.skip(8)) {
			return false;
		}
		out.kind = TlVal::Kind::Double;
		return true;
	}
	case 3: {
		QByteArray b;
		if (!r.readTlBytes(b)) {
			return false;
		}
		out.kind = TlVal::Kind::String;
		out.strVal = QString::fromUtf8(b);
		return true;
	}
	case 4: {
		QByteArray b;
		if (!r.readTlBytes(b)) {
			return false;
		}
		out.kind = TlVal::Kind::Bytes;
		return true;
	}
	case 5: {
		if (!r.skip(16)) {
			return false;
		}
		out.kind = TlVal::Kind::Bytes;
		return true;
	}
	case 6: {
		if (!r.skip(32)) {
			return false;
		}
		out.kind = TlVal::Kind::Bytes;
		return true;
	}
	case 7: {
		uint32_t c = 0;
		if (!r.readU32(c) || (c != kTlBoolTrue && c != kTlBoolFalse)) {
			return false;
		}
		out.kind = TlVal::Kind::Bool;
		out.boolVal = (c == kTlBoolTrue);
		return true;
	}
	case 8: {
		out.kind = TlVal::Kind::Bool;
		out.boolVal = true;
		return true;
	}
	case 9:
		return DecodeTlObj(s, r, depth + 1, out);
	case 12:
		if (targetIdx >= s.ctors.size()) {
			return false;
		}
		return DecodeTlFields(s, r, int(targetIdx), depth + 1, out);
	default:
		return false;
	}
}

bool DecodeTlFields(
		const TlSchemaData &s,
		TlReader &r,
		int ctorIdx,
		int depth,
		TlVal &out) {
	if (depth > 16 || ctorIdx < 0 || size_t(ctorIdx) >= s.ctors.size()) {
		return false;
	}
	const auto &c = s.ctors[ctorIdx];
	if (quint32(c.fstart) + quint32(c.fcount) > quint32(s.fields.size())) {
		return false;
	}
	out.kind = TlVal::Kind::Object;
	out.typeName = QString::fromUtf8(PoolStr(s, c.nameOff));
	out.fields.clear();
	std::vector<uint32_t> fvals;
	for (uint8_t i = 0; i < c.fcount; ++i) {
		const auto &f = s.fields[c.fstart + i];
		if (f.kind == 13) {
			uint32_t fl = 0;
			if (!r.readU32(fl)) {
				return false;
			}
			fvals.push_back(fl);
			continue;
		}
		if (f.flagSlot >= 0) {
			if (size_t(f.flagSlot) >= fvals.size() || f.flagBit >= 32) {
				return false;
			}
			if (((fvals[f.flagSlot] >> f.flagBit) & 1U) == 0) {
				continue;
			}
		}
		const auto fname = QString::fromUtf8(PoolStr(s, f.nameOff));
		if (f.kind == 8) {
			TlVal v;
			v.kind = TlVal::Kind::Bool;
			v.boolVal = true;
			out.fields.emplace_back(fname, std::move(v));
			continue;
		}
		if (f.kind == 10 || f.kind == 11) {
			if (f.kind == 10) {
				uint32_t vcid = 0;
				if (!r.readU32(vcid) || vcid != kTlVectorCid) {
					return false;
				}
			}
			qint32 n = 0;
			if (!r.readS32(n) || n < 0 || n > 100000) {
				return false;
			}
			TlVal listVal;
			listVal.kind = TlVal::Kind::List;
			listVal.list.reserve(size_t(n));
			for (qint32 j = 0; j < n; ++j) {
				TlVal elem;
				if (!DecodeTlVal(s, r, f.elemKind, f.targetIdx, depth + 1, elem)) {
					return false;
				}
				listVal.list.push_back(std::move(elem));
			}
			out.fields.emplace_back(fname, std::move(listVal));
			continue;
		}
		TlVal val;
		if (!DecodeTlVal(s, r, f.kind, f.targetIdx, depth, val)) {
			return false;
		}
		out.fields.emplace_back(fname, std::move(val));
	}
	return true;
}

bool DecodeTlObj(
		const TlSchemaData &s,
		TlReader &r,
		int depth,
		TlVal &out) {
	if (depth > 16) {
		return false;
	}
	uint32_t cid = 0;
	if (!r.readU32(cid) || cid == kTlVectorCid) {
		return false;
	}
	if (cid == kTlBoolTrue || cid == kTlBoolFalse) {
		out.kind = TlVal::Kind::Bool;
		out.boolVal = (cid == kTlBoolTrue);
		return true;
	}
	const int idx = FindCtorIdx(s, cid);
	if (idx < 0) {
		return false;
	}
	return DecodeTlFields(s, r, idx, depth, out);
}

QString TlPermForMethod(const QString &method) {
	if (method.isEmpty()) {
		return QString();
	}
	static const QSet<QString> denyMethods = {
		QStringLiteral("channels.deleteChannel"),
		QStringLiteral("channels.editCreator"),
		QStringLiteral("messages.deleteChat"),
		QStringLiteral("users.setSecureValueErrors"),
		QStringLiteral("contacts.resetSaved"),
		QStringLiteral("messages.deletePhoneCallHistory"),
	};
	if (denyMethods.contains(method)) {
		return QString();
	}
	if (method.startsWith(QStringLiteral("invoke"))
		|| method.startsWith(QStringLiteral("initConnection"))) {
		return QString();
	}
	const int dot = method.lastIndexOf('.');
	const QString head = (dot >= 0) ? method.left(dot) : QString();
	const QString tail = (dot >= 0) ? method.mid(dot + 1) : method;
	const bool readonly = tail.startsWith(QStringLiteral("get"))
		|| tail.startsWith(QStringLiteral("search"))
		|| tail.startsWith(QStringLiteral("resolve"))
		|| tail.startsWith(QStringLiteral("check"));
	if (head == QStringLiteral("auth")
		|| head == QStringLiteral("bots")
		|| head == QStringLiteral("smsjobs")
		|| head == QStringLiteral("langpack")
		|| head == QStringLiteral("phone")) {
		return QString();
	}
	if (head == QStringLiteral("account") || head == QStringLiteral("payments")) {
		if (!readonly) {
			return QString();
		}
		static const QStringList sensitiveWords = {
			QStringLiteral("Password"),
			QStringLiteral("Secure"),
			QStringLiteral("Authorization"),
			QStringLiteral("Takeout"),
			QStringLiteral("Passkey"),
			QStringLiteral("Phone"),
			QStringLiteral("Email"),
			QStringLiteral("Passport"),
		};
		for (const auto &w : sensitiveWords) {
			if (tail.contains(w)) {
				return QString();
			}
		}
	}
	return readonly ? QStringLiteral("tl.read") : QStringLiteral("tl.write");
}

