struct ParsedPluginInfo {
	QJsonObject meta;
	std::map<QString, QJsonValue> topVars;
	QStringList detected;
	QJsonArray evidence;
	QString error;
	QString sha256;
};

ParsedPluginInfo AnalyzePluginSource(const QString &source, const QByteArray &rawBytes) {
	ParsedPluginInfo res;
	res.sha256 = Sha256Hex(rawBytes);

	const QString cleanSource = (!source.isEmpty() && source[0] == QChar(0xFEFF))
		? source.mid(1)
		: source;
	const auto trimmed = cleanSource.trimmed();
	if (trimmed.isEmpty()) {
		res.error = Tr("пустой исходник");
		return res;
	}

	if (trimmed.startsWith('{')) {
		const QByteArray cleanRaw = rawBytes.startsWith("\xEF\xBB\xBF")
			? rawBytes.mid(3)
			: rawBytes;
		const auto jdoc = QJsonDocument::fromJson(cleanRaw);
		if (jdoc.isObject()) {
			const auto obj = jdoc.object();
			QJsonObject meta;
			if (obj.contains(QStringLiteral("__id__"))) {
				meta = obj;
			} else {
				const auto mapField = [&](const QString &srcKey, const QString &dstKey) {
					if (obj.contains(srcKey)) {
						meta.insert(dstKey, obj.value(srcKey));
					}
				};
				mapField(QStringLiteral("id"), QStringLiteral("__id__"));
				mapField(QStringLiteral("name"), QStringLiteral("__name__"));
				mapField(QStringLiteral("description"), QStringLiteral("__description__"));
				mapField(QStringLiteral("details"), QStringLiteral("__details__"));
				mapField(QStringLiteral("author"), QStringLiteral("__author__"));
				mapField(QStringLiteral("version"), QStringLiteral("__version__"));
				mapField(QStringLiteral("icon"), QStringLiteral("__icon__"));
				mapField(QStringLiteral("min_version"), QStringLiteral("__min_version__"));
				mapField(QStringLiteral("permissions"), QStringLiteral("__permissions__"));
				mapField(QStringLiteral("dependencies"), QStringLiteral("__dependencies__"));
			}
			res.meta = meta;
			return res;
		}
	}

	std::vector<PyTok> toks;
	QString lexErr;
	if (!TokenizePython(source, toks, lexErr)) {
		res.error = lexErr;
		return res;
	}

	struct EvidenceKey {
		QString cap;
		int line = 0;
		QString symbol;
		bool operator==(const EvidenceKey &o) const {
			return line == o.line && cap == o.cap && symbol == o.symbol;
		}
	};
	std::vector<EvidenceKey> evList;
	QSet<QString> detectedSet;
	auto recordCap = [&](const QString &cap, int line, const QString &sym) {
		detectedSet.insert(cap);
		if (int(evList.size()) >= 200) {
			return;
		}
		EvidenceKey k{ cap, line, sym };
		if (std::find(evList.begin(), evList.end(), k) == evList.end()) {
			evList.push_back(std::move(k));
		}
	};

	std::map<QString, QString> aliases;
	const auto &modCaps = ModuleCapMap();

	auto processStmt = [&](size_t s, size_t e) {
		if (s >= e) {
			return;
		}
		if (toks[s].kind == PyTok::Kind::Ident && toks[s].indent == 0) {
			const auto &kname = toks[s].text;
			if (s + 2 < e && toks[s + 1].kind == PyTok::Kind::Sym && toks[s + 1].text == QStringLiteral("=")) {
				const bool isDunder = kname.startsWith(QStringLiteral("__"))
					&& kname.endsWith(QStringLiteral("__"));
				const bool isDefaultVar = (kname == QStringLiteral("DEFAULT_WORD")
					|| kname == QStringLiteral("DEFAULT_TEXT"));
				if (isDunder || isDefaultVar) {
					size_t p = s + 2;
					QJsonValue litVal;
					if (EvalPyLiteral(toks, p, e, litVal) && p == e) {
						res.topVars[kname] = litVal;
						if (isDunder) {
							res.meta.insert(kname, litVal);
						}
					}
				}
			}
		}

		if (toks[s].kind == PyTok::Kind::Ident && toks[s].text == QStringLiteral("import")) {
			size_t p = s + 1;
			while (p < e) {
				if (toks[p].kind == PyTok::Kind::Ident) {
					QString full = toks[p].text;
					const QString rootMod = full;
					const int impLine = toks[p].line;
					++p;
					while (p + 1 < e && toks[p].kind == PyTok::Kind::Sym
						&& toks[p].text == QStringLiteral(".")
						&& toks[p + 1].kind == PyTok::Kind::Ident) {
						full.append('.');
						full.append(toks[p + 1].text);
						p += 2;
					}
					QString alias = rootMod;
					if (p + 1 < e && toks[p].kind == PyTok::Kind::Ident
						&& toks[p].text == QStringLiteral("as")
						&& toks[p + 1].kind == PyTok::Kind::Ident) {
						alias = toks[p + 1].text;
						p += 2;
					}
					aliases[alias] = full;
					const auto it = modCaps.find(rootMod);
					if (it != modCaps.end()) {
						recordCap(it->second, impLine, rootMod);
					}
				}
				if (p < e && toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral(",")) {
					++p;
				} else {
					break;
				}
			}
		} else if (toks[s].kind == PyTok::Kind::Ident && toks[s].text == QStringLiteral("from")) {
			size_t p = s + 1;
			while (p < e && toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral(".")) {
				++p;
			}
			QString modName;
			while (p < e && toks[p].kind == PyTok::Kind::Ident && toks[p].text != QStringLiteral("import")) {
				if (!modName.isEmpty()) {
					modName.append('.');
				}
				modName.append(toks[p].text);
				++p;
				if (p < e && toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral(".")) {
					++p;
				} else {
					break;
				}
			}
			if (p < e && toks[p].kind == PyTok::Kind::Ident && toks[p].text == QStringLiteral("import")) {
				const auto rootMod = modName.section('.', 0, 0);
				if (!rootMod.isEmpty()) {
					const auto it = modCaps.find(rootMod);
					if (it != modCaps.end()) {
						recordCap(it->second, toks[s].line, rootMod);
					}
				}
				++p;
				if (p < e && toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral("(")) {
					++p;
				}
				while (p < e) {
					if (toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral(")")) {
						break;
					}
					if (toks[p].kind == PyTok::Kind::Ident) {
						const QString item = toks[p].text;
						++p;
						QString alias = item;
						if (p + 1 < e && toks[p].kind == PyTok::Kind::Ident
							&& toks[p].text == QStringLiteral("as")
							&& toks[p + 1].kind == PyTok::Kind::Ident) {
							alias = toks[p + 1].text;
							p += 2;
						}
						aliases[alias] = modName.isEmpty() ? item : (modName + QStringLiteral(".") + item);
					}
					if (p < e && toks[p].kind == PyTok::Kind::Sym && toks[p].text == QStringLiteral(",")) {
						++p;
					} else {
						break;
					}
				}
			}
		}
	};

	size_t stmtStart = 0;
	for (size_t i = 0; i < toks.size(); ++i) {
		if (toks[i].kind == PyTok::Kind::Newline) {
			processStmt(stmtStart, i);
			stmtStart = i + 1;
		}
	}
	processStmt(stmtStart, toks.size());

	const auto &callCaps = CallCapMap();
	const auto &attrCaps = AttrCapMap();
	for (size_t i = 0; i + 1 < toks.size(); ++i) {
		if (toks[i].kind != PyTok::Kind::Sym || toks[i].text != QStringLiteral("(")) {
			continue;
		}
		if (i == 0 || toks[i - 1].kind != PyTok::Kind::Ident) {
			continue;
		}
		size_t chainStart = i - 1;
		while (chainStart >= 2
			&& toks[chainStart - 1].kind == PyTok::Kind::Sym
			&& toks[chainStart - 1].text == QStringLiteral(".")
			&& toks[chainStart - 2].kind == PyTok::Kind::Ident) {
			chainStart -= 2;
		}
		if (chainStart > 0 && toks[chainStart - 1].kind == PyTok::Kind::Ident
			&& (toks[chainStart - 1].text == QStringLiteral("def")
				|| toks[chainStart - 1].text == QStringLiteral("class"))) {
			continue;
		}
		QStringList chain;
		for (size_t k = chainStart; k <= i - 1; k += 2) {
			chain.push_back(toks[k].text);
		}
		const int callLine = toks[i - 1].line;
		const QString &name = chain.back();
		QString resolved;
		if (!chain.isEmpty()) {
			const auto itAlias = aliases.find(chain.front());
			if (itAlias != aliases.end()) {
				resolved = itAlias->second;
				for (int j = 1; j < chain.size(); ++j) {
					resolved.append('.');
					resolved.append(chain[j]);
				}
			} else {
				resolved = chain.join('.');
			}
		}
		const QString root = resolved.section('.', 0, 0);
		if (const auto it = modCaps.find(root); it != modCaps.end()) {
			recordCap(it->second, callLine, resolved);
		}
		if (resolved == QStringLiteral("os.system")
			|| resolved == QStringLiteral("os.popen")
			|| resolved == QStringLiteral("exec")
			|| resolved == QStringLiteral("eval")
			|| resolved == QStringLiteral("__import__")
			|| resolved == QStringLiteral("compile")) {
			recordCap(QStringLiteral("native"), callLine, resolved);
		}
		if (resolved == QStringLiteral("open")
			|| resolved == QStringLiteral("io.open")
			|| resolved == QStringLiteral("os.open")
			|| resolved == QStringLiteral("os.remove")
			|| resolved == QStringLiteral("os.unlink")
			|| resolved == QStringLiteral("os.rename")
			|| resolved == QStringLiteral("os.listdir")) {
			recordCap(QStringLiteral("files"), callLine, resolved);
		}
		if (const auto it = callCaps.find(name); it != callCaps.end()) {
			recordCap(it->second, callLine, name);
		}
		if (chain.size() == 1) {
			if (name == QStringLiteral("open")) {
				recordCap(QStringLiteral("files"), callLine, name);
			}
			if (name == QStringLiteral("exec")
				|| name == QStringLiteral("eval")
				|| name == QStringLiteral("__import__")
				|| name == QStringLiteral("compile")) {
				recordCap(QStringLiteral("native"), callLine, name);
			}
		} else {
			if (const auto it = attrCaps.find(name); it != attrCaps.end()) {
				recordCap(it->second, callLine, name);
			}
		}
	}

	QStringList sortedCaps;
	sortedCaps.reserve(detectedSet.size());
	for (const auto &cap : detectedSet) {
		sortedCaps.push_back(cap);
	}
	sortedCaps.sort();
	for (const auto &cap : sortedCaps) {
		bool found = false;
		for (const auto &ev : evList) {
			if (ev.cap == cap) {
				found = true;
				break;
			}
		}
		if (!found) {
			evList.push_back(EvidenceKey{ cap, 0, QString() });
		}
	}
	res.detected = std::move(sortedCaps);
	for (const auto &ev : evList) {
		QJsonObject o;
		o.insert(QStringLiteral("capability"), ev.cap);
		o.insert(QStringLiteral("line"), ev.line);
		o.insert(QStringLiteral("symbol"), ev.symbol);
		res.evidence.append(o);
	}
	return res;
}

struct TemplateSpec {
	const char *title = "";
	const char *wordLabel = "";
	const char *textLabel = "";
	QStringList perms;
	const char *descPattern = "";
};

const std::vector<TemplateSpec> &BuilderTemplates() {
	static const std::vector<TemplateSpec> specs = {
		{
			"Команда: пишете .слово, уходит текст",
			"Слово команды (без точки)",
			"Что отправить",
			{ QStringLiteral("messages.send"), QStringLiteral("settings") },
			"Пишете .%1, и вместо этого уходит заданный текст.",
		},
		{
			"Автозамена: слово меняется на текст",
			"Что заменять",
			"Чем заменять",
			{ QStringLiteral("messages.send"), QStringLiteral("settings") },
			"В каждом вашем сообщении слово «%1» меняется на заданный текст.",
		},
		{
			"Автоответ в личных чатах на слово",
			"Слово в сообщении",
			"Что ответить",
			{ QStringLiteral("messages.read"), QStringLiteral("messages.send"), QStringLiteral("settings") },
			"Когда в личные сообщения приходит слово «%1», плагин отвечает заданным текстом (не чаще раза в минуту на человека).",
		},
		{
			"Скрывать сообщения со словом",
			"Слово или фраза",
			"Не используется",
			{ QStringLiteral("messages.read"), QStringLiteral("settings") },
			"Сообщения со словом «%1» скрываются у вас в чате. На сервере ничего не меняется.",
		},
	};
	return specs;
}

int DetectBuilderKind(const QString &source) {
	const auto lines = source.split('\n');
	const int checkLines = std::min(int(lines.size()), 16);
	for (int i = 0; i < checkLines; ++i) {
		const auto trimmed = lines[i].trimmed();
		if (trimmed.startsWith(QStringLiteral("# moka-template:"))) {
			bool ok = false;
			const int k = trimmed.mid(16).trimmed().toInt(&ok);
			if (ok && k >= 0 && k <= 3) {
				return k;
			}
		}
	}
	if (source.contains(QStringLiteral("class Mine(BasePlugin):"))
		&& source.contains(QStringLiteral("DEFAULT_WORD"))
		&& source.contains(QStringLiteral("DEFAULT_TEXT"))) {
		if (source.contains(QStringLiteral("text.lstrip('.').lower() == word and text.startswith('.')"))) {
			return 0;
		}
		if (source.contains(QStringLiteral("params['text'].replace(word, str(api.get_setting('text', DEFAULT_TEXT)"))) {
			return 1;
		}
		if (source.contains(QStringLiteral("def on_new_message(self, m):"))
			&& source.contains(QStringLiteral("self.last[m['peer']] = now"))) {
			return 2;
		}
		if (source.contains(QStringLiteral("def message_filter_hook(self, message):"))
			&& source.contains(QStringLiteral("word in (message.get('text') or '').lower()"))) {
			return 3;
		}
	}
	return -1;
}

QString BuildBuilderSource(const QString &name, int kind, const QString &word, const QString &text) {
	const auto &tpls = BuilderTemplates();
	const auto &tpl = tpls[size_t(kind)];
	QString slug;
	for (const QChar c : name.toLower()) {
		const ushort u = c.unicode();
		if ((u >= 'a' && u <= 'z') || (u >= '0' && u <= '9')) {
			slug.append(c);
			if (slug.size() >= 14) {
				break;
			}
		}
	}
	if (slug.isEmpty()) {
		slug = QStringLiteral("my");
	}
	const quint32 suffix = base::RandomValue<quint32>() % 10000U;
	const QString pid = QStringLiteral("my_") + slug + QStringLiteral("_")
		+ QString::number(suffix).rightJustified(4, QChar('0'));
	const QString wordForDesc = (kind == 0 && word.startsWith('.')) ? word.mid(1) : word;
	const QString desc = Tr(tpl.descPattern).arg(wordForDesc);
	const QString details = Tr("%1\nШаблон: %2.\nСоздан в конструкторе плагинов. Слово и текст меняются в настройках плагина (Кастомизация, раздел «Плагины», или значок шестерёнки на карточке).")
		.arg(desc, Tr(tpl.title));
	const QString permsStr = QString::fromUtf8(
		QJsonDocument([&] {
			QJsonArray arr;
			for (const auto &p : tpl.perms) {
				arr.append(p);
			}
			return arr;
		}()).toJson(QJsonDocument::Compact));

	QStringList out;
	out.push_back(QStringLiteral("# moka-template: ") + QString::number(kind));
	out.push_back(QStringLiteral("__id__ = ") + PyReprString(pid));
	out.push_back(QStringLiteral("__name__ = ") + PyReprString(name));
	out.push_back(QStringLiteral("__description__ = ") + PyReprString(desc.left(200)));
	out.push_back(QStringLiteral("__details__ = ") + PyReprString(details));
	out.push_back(QStringLiteral("__author__ = ") + PyReprString(Tr("вы")));
	out.push_back(QStringLiteral("__version__ = '1.0.0'"));
	out.push_back(QString::fromUtf8("__icon__ = '\xE2\x9C\x8F\xEF\xB8\x8F'"));
	out.push_back(QStringLiteral("__min_version__ = '0.1.0'"));
	out.push_back(QStringLiteral("__permissions__ = ") + permsStr);
	out.push_back(QString());
	out.push_back(QStringLiteral("import time"));
	out.push_back(QString());
	out.push_back(QStringLiteral("from base_plugin import BasePlugin, HookResult, HookStrategy, Input, Switch"));
	out.push_back(QStringLiteral("from mokagram_sdk import api"));
	out.push_back(QString());
	out.push_back(QStringLiteral("DEFAULT_WORD = ") + PyReprString(word));
	out.push_back(QStringLiteral("DEFAULT_TEXT = ") + PyReprString(text));
	out.push_back(QString());
	out.push_back(QString());
	out.push_back(QStringLiteral("class Mine(BasePlugin):"));
	out.push_back(QStringLiteral("    def create_settings(self):"));
	out.push_back(QStringLiteral("        return ["));
	out.push_back(QStringLiteral("            Switch(key='enabled', text=") + PyReprString(Tr("Включён")) + QStringLiteral(", default=True),"));
	out.push_back(QStringLiteral("            Input(key='word', text=") + PyReprString(Tr(tpl.wordLabel)) + QStringLiteral(", default=DEFAULT_WORD),"));
	if (kind != 3) {
		out.push_back(QStringLiteral("            Input(key='text', text=") + PyReprString(Tr(tpl.textLabel)) + QStringLiteral(", default=DEFAULT_TEXT),"));
	}
	out.push_back(QStringLiteral("        ]"));
	out.push_back(QString());
	if (kind == 0) {
		out.push_back(QStringLiteral("    def send_message_hook(self, params):"));
		out.push_back(QStringLiteral("        text = (params.get('text') or '').strip()"));
		out.push_back(QStringLiteral("        word = str(api.get_setting('word', DEFAULT_WORD) or '').strip().lstrip('.').lower()"));
		out.push_back(QStringLiteral("        if api.get_setting('enabled', True) and word and text.lstrip('.').lower() == word and text.startswith('.'):"));
		out.push_back(QStringLiteral("            params['text'] = str(api.get_setting('text', DEFAULT_TEXT) or '')"));
		out.push_back(QStringLiteral("            return HookResult(HookStrategy.MODIFY, params)"));
		out.push_back(QStringLiteral("        return HookResult()"));
	} else if (kind == 1) {
		out.push_back(QStringLiteral("    def send_message_hook(self, params):"));
		out.push_back(QStringLiteral("        word = str(api.get_setting('word', DEFAULT_WORD) or '')"));
		out.push_back(QStringLiteral("        if api.get_setting('enabled', True) and word and word in (params.get('text') or ''):"));
		out.push_back(QStringLiteral("            params['text'] = params['text'].replace(word, str(api.get_setting('text', DEFAULT_TEXT) or ''))"));
		out.push_back(QStringLiteral("            return HookResult(HookStrategy.MODIFY, params)"));
		out.push_back(QStringLiteral("        return HookResult()"));
	} else if (kind == 2) {
		out.push_back(QStringLiteral("    def on_plugin_load(self):"));
		out.push_back(QStringLiteral("        self.last = {}"));
		out.push_back(QString());
		out.push_back(QStringLiteral("    def on_new_message(self, m):"));
		out.push_back(QStringLiteral("        if m.get('out') or m.get('peer_kind') not in ('user',) or not api.get_setting('enabled', True):"));
		out.push_back(QStringLiteral("            return"));
		out.push_back(QStringLiteral("        word = str(api.get_setting('word', DEFAULT_WORD) or '').lower()"));
		out.push_back(QStringLiteral("        if not word or word not in (m.get('text') or '').lower():"));
		out.push_back(QStringLiteral("            return"));
		out.push_back(QStringLiteral("        now = time.time()"));
		out.push_back(QStringLiteral("        if now - self.last.get(m['peer'], 0) < 60:"));
		out.push_back(QStringLiteral("            return"));
		out.push_back(QStringLiteral("        self.last[m['peer']] = now"));
		out.push_back(QStringLiteral("        api.send_message(m['peer'], str(api.get_setting('text', DEFAULT_TEXT) or ''))"));
	} else {
		out.push_back(QStringLiteral("    def message_filter_hook(self, message):"));
		out.push_back(QStringLiteral("        word = str(api.get_setting('word', DEFAULT_WORD) or '').lower()"));
		out.push_back(QStringLiteral("        return bool(api.get_setting('enabled', True) and word and word in (message.get('text') or '').lower())"));
	}
	out.push_back(QString());
	return out.join('\n');
}

void DeactivatePlugin(const QString &pid, const QString &targetState, const QString &targetError) {
	bool hadActiveBridge = false;
	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(pid);
		if (it != _plugins.end()) {
			auto &e = it->second;
			hadActiveBridge = (e.state == QStringLiteral("loaded") || e.filterActive || e.eventsActive);
			e.filterActive = false;
			e.eventsActive = false;
			e.tplCooldowns.clear();
			e.state = targetState;
			e.error = targetError;
		}
	}
	if (hadActiveBridge) {
		CallBridgeJson("plugin_unloaded", QJsonObject{ { QStringLiteral("pid"), pid } });
	}
}

bool ActivateTemplatePlugin(const QString &pid, const LogFn &log) {
	int tplKind = -1;
	bool tplEnabled = true;
	QString tplWord;
	QString tplText;
	QString tplWordLabel;
	QString tplTextLabel;
	QString displayName;
	QString icon;
	bool hasReadGrant = false;
	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(pid);
		if (it == _plugins.end()) {
			return false;
		}
		auto &e = it->second;
		tplKind = e.tplKind;
		tplEnabled = e.tplEnabled;
		tplWord = e.tplWord;
		tplText = e.tplText;
		tplWordLabel = e.tplWordLabel;
		tplTextLabel = e.tplTextLabel;
		displayName = e.name.isEmpty() ? e.id : e.name;
		icon = e.icon;
		hasReadGrant = HasGrantLocked(pid, QStringLiteral("messages.read"));
	}

	QJsonArray entries;
	const QString iconValue = (!icon.isEmpty() && !icon.contains('/'))
		? (QStringLiteral("alt:") + icon.left(8))
		: QString();

	QJsonObject enItem;
	enItem.insert(QStringLiteral("key"), QStringLiteral("plugin.") + pid + QStringLiteral(".enabled"));
	enItem.insert(QStringLiteral("section"), displayName);
	enItem.insert(QStringLiteral("title"), Tr("Включён"));
	enItem.insert(QStringLiteral("description"), QString());
	if (!iconValue.isEmpty()) {
		enItem.insert(QStringLiteral("icon"), iconValue);
	}
	enItem.insert(QStringLiteral("kind"), QStringLiteral("bool"));
	enItem.insert(QStringLiteral("default"), tplEnabled);
	entries.append(enItem);

	QJsonObject wItem;
	wItem.insert(QStringLiteral("key"), QStringLiteral("plugin.") + pid + QStringLiteral(".word"));
	wItem.insert(QStringLiteral("section"), displayName);
	wItem.insert(QStringLiteral("title"), tplWordLabel);
	wItem.insert(QStringLiteral("description"), QString());
	if (!iconValue.isEmpty()) {
		wItem.insert(QStringLiteral("icon"), iconValue);
	}
	wItem.insert(QStringLiteral("kind"), QStringLiteral("string"));
	wItem.insert(QStringLiteral("default"), tplWord.left(500));
	entries.append(wItem);

	QStringList keys = { QStringLiteral("enabled"), QStringLiteral("word") };
	if (tplKind != 3) {
		QJsonObject tItem;
		tItem.insert(QStringLiteral("key"), QStringLiteral("plugin.") + pid + QStringLiteral(".text"));
		tItem.insert(QStringLiteral("section"), displayName);
		tItem.insert(QStringLiteral("title"), tplTextLabel);
		tItem.insert(QStringLiteral("description"), QString());
		if (!iconValue.isEmpty()) {
			tItem.insert(QStringLiteral("icon"), iconValue);
		}
		tItem.insert(QStringLiteral("kind"), QStringLiteral("string"));
		tItem.insert(QStringLiteral("default"), tplText.left(500));
		entries.append(tItem);
		keys.push_back(QStringLiteral("text"));
	}

	CallBridgeJson("settings_register", QJsonObject{ { QStringLiteral("entries"), entries } });

	const auto readBoolSetting = [&](const QString &k, bool defVal) -> bool {
		const auto r = CallBridgeJson("setting_get", QJsonObject{
			{ QStringLiteral("key"), QStringLiteral("plugin.") + pid + QStringLiteral(".") + k },
		});
		return r.value(QStringLiteral("ok")).toBool() ? r.value(QStringLiteral("v")).toBool(defVal) : defVal;
	};
	const auto readStrSetting = [&](const QString &k, const QString &defVal) -> QString {
		const auto r = CallBridgeJson("setting_get", QJsonObject{
			{ QStringLiteral("key"), QStringLiteral("plugin.") + pid + QStringLiteral(".") + k },
		});
		return r.value(QStringLiteral("ok")).toBool() ? r.value(QStringLiteral("v")).toString(defVal) : defVal;
	};
	const bool curEnabled = readBoolSetting(QStringLiteral("enabled"), tplEnabled);
	const QString curWord = readStrSetting(QStringLiteral("word"), tplWord);
	const QString curText = (tplKind != 3) ? readStrSetting(QStringLiteral("text"), tplText) : QString();

	bool filterSubscribed = false;
	bool eventsSubscribed = false;
	QString permWarning;
	if (tplKind == 3) {
		if (!hasReadGrant) {
			permWarning = Tr("[%1] message_filter_hook: нет права messages.read").arg(pid);
		} else {
			CallBridgeJson("filter_subscribe", QJsonObject{
				{ QStringLiteral("pid"), pid },
				{ QStringLiteral("on"), curEnabled },
			});
			filterSubscribed = curEnabled;
		}
	} else if (tplKind == 2) {
		if (!hasReadGrant) {
			permWarning = Tr("[%1] события сообщений: нет права messages.read, не подписан").arg(pid);
			AppendAudit(pid, QString(), QStringLiteral("events.subscribe"), QStringLiteral("new_message"), QStringLiteral("denied"), 0);
		} else {
			AppendAudit(pid, QString(), QStringLiteral("events.subscribe"), QStringLiteral("new_message"), QStringLiteral("allowed"), 0);
			CallBridgeJson("events_subscribe", QJsonObject{
				{ QStringLiteral("pid"), pid },
				{ QStringLiteral("events"), QJsonArray{ QStringLiteral("new_message") } },
			});
			eventsSubscribed = true;
		}
	}

	if (!permWarning.isEmpty()) {
		EmitLog(log, permWarning);
	}

	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(pid);
		if (it != _plugins.end()) {
			auto &e = it->second;
			e.state = QStringLiteral("loaded");
			e.error.clear();
			e.hasSettings = true;
			e.settingKeys = keys;
			e.boolSettings = QSet<QString>{ QStringLiteral("enabled") };
			e.tplEnabled = curEnabled;
			e.tplWord = curWord;
			e.tplText = curText;
			e.filterActive = filterSubscribed;
			e.eventsActive = eventsSubscribed;
			e.tplCooldowns.clear();
		}
	}
	EmitLog(log, Tr("[%1] плагин работает (шаблон)").arg(pid));
	return true;
}

QString LoadFileImpl(const QString &fileName, const LogFn &log, bool recordGrantInDev) {
	const QString fullPath = PluginsDirQ() + QStringLiteral("/") + fileName;
	const QFileInfo fileInfo(fullPath);
	if (!fileInfo.isFile() || fileInfo.isSymLink() || fileInfo.size() < 0 || fileInfo.size() > kPluginFileLimitBytes) {
		EmitLog(log, fileName + QStringLiteral(": skipped (invalid, symlink, or > 1 MB)"));
		return QString();
	}
	QFile f(fullPath);
	if (!f.open(QIODevice::ReadOnly)) {
		EmitLog(log, fileName + QStringLiteral(": ") + f.errorString());
		return QString();
	}
	const QByteArray raw = f.readAll();
	f.close();
	const QString source = QString::fromUtf8(raw);
	const auto info = AnalyzePluginSource(source, raw);

	const QString metaId = info.meta.value(QStringLiteral("__id__")).toString();
	const QString pid = metaId.isEmpty() ? fileName : metaId;

	DeactivatePlugin(pid, QStringLiteral("error"), QString());

	PluginEntry entry;
	entry.id = pid;
	entry.file = fileName;
	entry.path = fullPath;
	entry.name = info.meta.value(QStringLiteral("__name__")).toString();
	entry.description = info.meta.value(QStringLiteral("__description__")).toString();
	entry.details = info.meta.value(QStringLiteral("__details__")).toString().left(4000);
	entry.author = info.meta.value(QStringLiteral("__author__")).toString();
	entry.version = info.meta.value(QStringLiteral("__version__")).toString();
	entry.icon = info.meta.value(QStringLiteral("__icon__")).toString();
	entry.permissions = info.meta.value(QStringLiteral("__permissions__")).toArray();
	for (const auto &v : entry.permissions) {
		if (v.isString()) {
			entry.declaredPerms.push_back(v.toString());
		}
	}
	for (const auto &v : info.meta.value(QStringLiteral("__dependencies__")).toArray()) {
		if (v.isString()) {
			entry.dependencies.push_back(v.toString());
		}
	}

	const int tplKind = DetectBuilderKind(source);
	if (tplKind >= 0) {
		const auto &tpls = BuilderTemplates();
		entry.tplKind = tplKind;
		entry.tplWordLabel = Tr(tpls[size_t(tplKind)].wordLabel);
		entry.tplTextLabel = Tr(tpls[size_t(tplKind)].textLabel);
		if (auto it = info.topVars.find(QStringLiteral("DEFAULT_WORD")); it != info.topVars.end()) {
			entry.tplWord = it->second.toString();
		}
		if (auto it = info.topVars.find(QStringLiteral("DEFAULT_TEXT")); it != info.topVars.end()) {
			entry.tplText = it->second.toString();
		}
	}

	const QString digest = info.sha256;
	enum class Action {
		None,
		ActivateTemplate,
	};
	Action action = Action::None;
	QStringList pendingLogs;
	QString auditDecision;

	{
		std::lock_guard lock(_dataMutex);
		if (!info.error.isEmpty() || metaId.isEmpty()) {
			entry.state = QStringLiteral("error");
			entry.error = !info.error.isEmpty() ? info.error : Tr("нет поля __id__");
		} else if (_disabled.contains(pid)) {
			entry.state = QStringLiteral("disabled");
		} else if (!_engineEnabled.load()) {
			entry.state = QStringLiteral("paused");
		} else {
			QStringList missingDeps;
			for (const auto &dep : entry.dependencies) {
				const auto dit = _plugins.find(dep);
				if (dit == _plugins.end() || dit->second.state != QStringLiteral("loaded")) {
					missingDeps.push_back(dep);
				}
			}
			if (!missingDeps.isEmpty()) {
				entry.state = QStringLiteral("error");
				entry.error = Tr("нужны плагины: ") + missingDeps.join(QStringLiteral(", "));
			} else {
				const auto git = _grants.find(pid);
				const bool dev = IsDevMode() || recordGrantInDev;
				if (git == _grants.end()) {
					if (dev) {
						_grants[pid] = GrantRecord{ digest, ComputeDefaultGrants(entry.declaredPerms) };
						SaveGrantsLocked(pendingLogs);
						action = Action::ActivateTemplate;
					} else {
						entry.state = QStringLiteral("needs_review");
						pendingLogs.push_back(Tr("[%1] плагин неизвестного происхождения, не запущен до подтверждения").arg(pid));
						auditDecision = QStringLiteral("needs_review");
					}
				} else if (git->second.hash != digest && !dev) {
					entry.state = QStringLiteral("needs_review");
					pendingLogs.push_back(Tr("[%1] файл изменился после установки, плагин не запущен до подтверждения").arg(pid));
					auditDecision = QStringLiteral("needs_review");
				} else {
					if (git->second.hash != digest && dev) {
						_grants[pid] = GrantRecord{ digest, ComputeDefaultGrants(entry.declaredPerms) };
						SaveGrantsLocked(pendingLogs);
						pendingLogs.push_back(QStringLiteral("[dev] ") + pid + QStringLiteral(": updated hash"));
					}
					action = Action::ActivateTemplate;
				}
			}
		}

		if (action == Action::ActivateTemplate && tplKind < 0) {
			entry.state = QStringLiteral("error");
			entry.error = Tr("Этот плагин использует код Python. В этой сборке работают плагины из конструктора.");
			pendingLogs.push_back(QStringLiteral("[") + pid + QStringLiteral("] ") + entry.error);
			action = Action::None;
		}

		const bool existed = (_plugins.find(pid) != _plugins.end());
		_plugins[pid] = std::move(entry);
		if (!existed) {
			_pluginOrder.push_back(pid);
		}
	}

	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}
	if (!auditDecision.isEmpty()) {
		AppendAudit(pid, digest, QStringLiteral("load"), QString(), auditDecision, 0);
	}
	if (action == Action::ActivateTemplate) {
		ActivateTemplatePlugin(pid, log);
	}
	return pid;
}

std::vector<QString> TopologicalPluginFiles(const QString &dirPath) {
	struct FileItem {
		QString id;
		QStringList deps;
	};
	QStringList files;
	const auto dir = QDir(dirPath);
	if (dir.exists()) {
		files = dir.entryList({ QStringLiteral("*.plugin") }, QDir::Files | QDir::NoSymLinks, QDir::Name);
	}
	std::map<QString, FileItem> items;
	std::map<QString, QString> byId;
	for (const auto &name : files) {
		FileItem fi;
		fi.id = name;
		const QString fpath = dirPath + QStringLiteral("/") + name;
		const QFileInfo finfo(fpath);
		QFile f(fpath);
		if (finfo.isFile() && !finfo.isSymLink() && finfo.size() >= 0 && finfo.size() <= kPluginFileLimitBytes && f.open(QIODevice::ReadOnly)) {
			const QByteArray raw = f.readAll();
			const auto parsed = AnalyzePluginSource(QString::fromUtf8(raw), raw);
			const auto mid = parsed.meta.value(QStringLiteral("__id__")).toString();
			if (!mid.isEmpty()) {
				fi.id = mid;
			}
			for (const auto &v : parsed.meta.value(QStringLiteral("__dependencies__")).toArray()) {
				if (v.isString()) {
					fi.deps.push_back(v.toString());
				}
			}
		}
		byId[fi.id] = name;
		items[name] = std::move(fi);
	}

	std::vector<QString> order;
	QSet<QString> seen;
	auto visit = [&](auto &self, const QString &name, QSet<QString> &stack) -> void {
		if (seen.contains(name) || stack.contains(name)) {
			return;
		}
		stack.insert(name);
		const auto it = items.find(name);
		if (it != items.end()) {
			for (const auto &dep : it->second.deps) {
				const auto bit = byId.find(dep);
				if (bit != byId.end()) {
					self(self, bit->second, stack);
				}
			}
		}
		stack.remove(name);
		seen.insert(name);
		order.push_back(name);
	};
	for (const auto &name : files) {
		QSet<QString> stack;
		visit(visit, name, stack);
	}
	return order;
}

QString CurrentPrefix() {
	{
		std::lock_guard lock(_prefixMutex);
		if (_prefixCheckedAt != SteadyClock::time_point::min()
			&& (SteadyClock::now() - _prefixCheckedAt) < std::chrono::seconds(5)) {
			return _prefixCached;
		}
	}
	const auto r = CallBridgeJson("client_setting_get", QJsonObject{
		{ QStringLiteral("key"), QStringLiteral("plugins.prefix") },
	});
	QString val = QStringLiteral(".");
	if (r.value(QStringLiteral("ok")).toBool()) {
		const auto raw = r.value(QStringLiteral("v")).toString().trimmed();
		if (!raw.isEmpty()) {
			val = raw.left(2);
		}
	}
	std::lock_guard lock(_prefixMutex);
	_prefixCheckedAt = SteadyClock::now();
	_prefixCached = val;
	return val;
}

bool DevReloadEnabled() {
	if (qEnvironmentVariable("MOKAGRAM_DEV_RELOAD") == QStringLiteral("1")) {
		return true;
	}
	if (_stopping.load()) {
		return false;
	}
	const auto r = CallBridgeJson("client_setting_get", QJsonObject{
		{ QStringLiteral("key"), QStringLiteral("plugins.dev_reload") },
	});
	return r.value(QStringLiteral("ok")).toBool() && r.value(QStringLiteral("v")).toBool(false);
}

QString FwTlId(const QString &peerStr) {
	bool ok = false;
	const quint64 n = peerStr.toULongLong(&ok);
	if (!ok) {
		return peerStr;
	}
	constexpr quint64 bit49 = quint64(1) << 49;
	constexpr quint64 bit48 = quint64(1) << 48;
	if (n >= bit49) {
		return QStringLiteral("-100") + QString::number(n - bit49);
	}
	if (n >= bit48) {
		return QStringLiteral("-") + QString::number(n - bit48);
	}
	return QString::number(n);
}

QStringList SplitShellArgs(const QString &input) {
	QStringList out;
	QString cur;
	bool inToken = false;
	QChar quote;
	for (int i = 0; i < input.size(); ++i) {
		const QChar c = input[i];
		if (!quote.isNull()) {
			if (c == quote) {
				quote = QChar();
			} else if (c == '\\' && quote == '"' && i + 1 < input.size()) {
				cur.append(input[++i]);
			} else {
				cur.append(c);
			}
		} else if (c == '\'' || c == '"') {
			quote = c;
			inToken = true;
		} else if (c == '\\' && i + 1 < input.size()) {
			cur.append(input[++i]);
			inToken = true;
		} else if (c.isSpace()) {
			if (inToken) {
				out.push_back(cur);
				cur.clear();
				inToken = false;
			}
		} else {
			cur.append(c);
			inToken = true;
		}
	}
	if (!quote.isNull()) {
		return input.split(QRegularExpression(QStringLiteral("\\s+")), Qt::SkipEmptyParts);
	}
	if (inToken) {
		out.push_back(cur);
	}
	return out;
}

bool IsBlockedIpAddress(const QHostAddress &addr) {
	if (addr.isNull() || !addr.scopeId().isEmpty()
		|| addr.isLoopback() || addr.isLinkLocal() || addr.isMulticast()
		|| addr.isBroadcast() || addr.isPrivateUse()) {
		return true;
	}
	if (addr == QHostAddress(QHostAddress::Any)
		|| addr == QHostAddress(QHostAddress::AnyIPv4)
		|| addr == QHostAddress(QHostAddress::AnyIPv6)) {
		return true;
	}
	const auto isBlockedV4 = [](quint32 ip4) -> bool {
		const auto inRange = [&](quint32 net, int bits) {
			const quint32 mask = bits == 0 ? 0U : (0xFFFFFFFFU << (32 - bits));
			return (ip4 & mask) == (net & mask);
		};
		return inRange(0x00000000U, 8)
			|| inRange(0x0A000000U, 8)
			|| inRange(0x64400000U, 10)
			|| inRange(0x7F000000U, 8)
			|| inRange(0xA9FE0000U, 16)
			|| inRange(0xAC100000U, 12)
			|| inRange(0xC0000000U, 24)
			|| inRange(0xC0000200U, 24)
			|| inRange(0xC0586300U, 24)
			|| inRange(0xC0A80000U, 16)
			|| inRange(0xC6120000U, 15)
			|| inRange(0xC6336400U, 24)
			|| inRange(0xCB007100U, 24)
			|| inRange(0xE0000000U, 3);
	};
	bool isV4 = false;
	const quint32 ip4 = addr.toIPv4Address(&isV4);
	if (isV4) {
		return isBlockedV4(ip4);
	}
	const Q_IPV6ADDR a6 = addr.toIPv6Address();
	auto u32At = [&](int off) -> quint32 {
		return (quint32(a6[off]) << 24)
			| (quint32(a6[off + 1]) << 16)
			| (quint32(a6[off + 2]) << 8)
			| quint32(a6[off + 3]);
	};
	bool prefixZero = true;
	for (int i = 0; i < 15; ++i) {
		if (a6[i] != 0) {
			prefixZero = false;
			break;
		}
	}
	if (prefixZero && (a6[15] == 0 || a6[15] == 1)) {
		return true;
	}
	if ((a6[0] & 0xFEU) == 0xFCU) {
		return true;
	}
	if (a6[0] == 0xFEU && (a6[1] & 0x80U) == 0x80U) {
		return true;
	}
	if (a6[0] == 0xFFU) {
		return true;
	}
	const quint32 w0 = u32At(0);
	const quint32 w1 = u32At(4);
	const quint32 w2 = u32At(8);
	const quint32 w3 = u32At(12);
	if (w0 == 0x01000000U && w1 == 0U) {
		return true;
	}
	if (w0 == 0x20010DB8U) {
		return true;
	}
	if (w0 == 0x20010002U && a6[4] == 0U && a6[5] == 0U) {
		return true;
	}
	if (w0 == 0x0064FF9BU && a6[4] == 0U && a6[5] == 0x01U) {
		return true;
	}
	if (w0 == 0U && w1 == 0U && w2 == 0U) {
		return isBlockedV4(w3);
	}
	if (w0 == 0U && w1 == 0U && w2 == 0x0000FFFFU) {
		return isBlockedV4(w3);
	}
	if (w0 == 0U && w1 == 0x0000FFFFU && w2 == 0U) {
		return isBlockedV4(w3);
	}
	if (w0 == 0x0064FF9BU && w1 == 0U && w2 == 0U) {
		return isBlockedV4(w3);
	}
	if (a6[0] == 0x20U && a6[1] == 0x02U) {
		const quint32 embedded = (quint32(a6[2]) << 24)
			| (quint32(a6[3]) << 16)
			| (quint32(a6[4]) << 8)
			| quint32(a6[5]);
		if (isBlockedV4(embedded)) {
			return true;
		}
	}
	if (w0 == 0x20010000U) {
		if (isBlockedV4(w3 ^ 0xFFFFFFFFU) || isBlockedV4(w1)) {
			return true;
		}
	}
	return false;
}

bool ValidateSafeHttpUrl(const QUrl &url, QString &errOut) {
	const auto scheme = url.scheme().toLower();
	if (!url.isValid() || (scheme != QStringLiteral("http") && scheme != QStringLiteral("https"))) {
		errOut = Tr("допустимы только http и https");
		return false;
	}
	QString cleanHost = url.host();
	if (cleanHost.startsWith('[') && cleanHost.endsWith(']') && cleanHost.size() >= 2) {
		cleanHost = cleanHost.mid(1, cleanHost.size() - 2);
	}
	if (cleanHost.isEmpty()) {
		errOut = Tr("неверный адрес");
		return false;
	}
	QHostAddress literal;
	if (literal.setAddress(cleanHost)) {
		if (IsBlockedIpAddress(literal)) {
			errOut = Tr("адрес во внутренней сети закрыт");
			return false;
		}
		return true;
	}
	const auto resolved = QHostInfo::fromName(cleanHost);
	const auto addrs = resolved.addresses();
	if (resolved.error() != QHostInfo::NoError || addrs.isEmpty()) {
		errOut = resolved.errorString().isEmpty() ? Tr("неверный адрес") : resolved.errorString();
		return false;
	}
	for (const auto &a : addrs) {
		if (IsBlockedIpAddress(a)) {
			errOut = Tr("адрес во внутренней сети закрыт");
			return false;
		}
	}
	return true;
}

bool DownloadSafePluginFile(const QString &urlStr, const QString &destPath, QString &errOut) {
	QUrl curUrl(urlStr);
	QNetworkAccessManager nam;
	QByteArray result;

	for (int hops = 0; hops <= kHttpMaxRedirects; ++hops) {
		if (!ValidateSafeHttpUrl(curUrl, errOut)) {
			return false;
		}
		QNetworkRequest req(curUrl);
		req.setRawHeader("User-Agent", "Mokagram");
		req.setAttribute(QNetworkRequest::RedirectPolicyAttribute, QNetworkRequest::ManualRedirectPolicy);
		req.setTransferTimeout(kHttpTimeoutMs);

		auto *reply = nam.get(req);
		QEventLoop loop;
		bool tooLarge = false;
		bool timedOut = false;

		QObject::connect(reply, &QNetworkReply::downloadProgress, &loop, [&](qint64 received, qint64) {
			if (received > kPluginFileLimitBytes) {
				tooLarge = true;
				reply->abort();
			}
		});
		QObject::connect(reply, &QNetworkReply::readyRead, &loop, [&] {
			if (reply->bytesAvailable() + result.size() > kPluginFileLimitBytes) {
				tooLarge = true;
				reply->abort();
			}
		});
		QObject::connect(reply, &QNetworkReply::finished, &loop, &QEventLoop::quit);

		QTimer timeoutTimer;
		timeoutTimer.setSingleShot(true);
		QObject::connect(&timeoutTimer, &QTimer::timeout, &loop, [&] {
			timedOut = true;
			reply->abort();
		});
		timeoutTimer.start(kHttpTimeoutMs);

		QTimer stopPoll;
		QObject::connect(&stopPoll, &QTimer::timeout, &loop, [&] {
			if (_stopping.load()) {
				reply->abort();
			}
		});
		stopPoll.start(200);

		loop.exec();
		timeoutTimer.stop();
		stopPoll.stop();

		if (_stopping.load()) {
			reply->deleteLater();
			errOut = Tr("таймаут загрузки");
			return false;
		}
		if (tooLarge) {
			reply->deleteLater();
			errOut = Tr("ответ больше 1 МБ");
			return false;
		}
		if (timedOut) {
			reply->deleteLater();
			errOut = Tr("таймаут загрузки");
			return false;
		}

		const int status = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
		if (status == 301 || status == 302 || status == 303 || status == 307 || status == 308) {
			const auto loc = reply->attribute(QNetworkRequest::RedirectionTargetAttribute).toUrl();
			reply->deleteLater();
			if (!loc.isValid()) {
				errOut = Tr("неверный адрес");
				return false;
			}
			curUrl = curUrl.resolved(loc);
			if (hops == kHttpMaxRedirects) {
				errOut = Tr("слишком много перенаправлений");
				return false;
			}
			continue;
		}

		if (status != 0 && status != 200) {
			reply->deleteLater();
			errOut = QStringLiteral("HTTP ") + QString::number(status);
			return false;
		}
		if (reply->error() != QNetworkReply::NoError) {
			errOut = reply->errorString();
			reply->deleteLater();
			return false;
		}
		if (status != 200) {
			reply->deleteLater();
			errOut = QStringLiteral("HTTP ") + QString::number(status);
			return false;
		}
		result = reply->readAll();
		reply->deleteLater();
		if (result.size() > kPluginFileLimitBytes) {
			errOut = Tr("ответ больше 1 МБ");
			return false;
		}
		if (result.isEmpty()) {
			errOut = Tr("ответ сервера пустой");
			return false;
		}
		QFile out(destPath);
		if (!out.open(QIODevice::WriteOnly | QIODevice::Truncate)
			|| out.write(result) != result.size()) {
			errOut = Tr("не удалось записать файл плагина");
			return false;
		}
		return true;
	}
	errOut = Tr("слишком много перенаправлений");
	return false;
}

bool IsUnsafeArchivePath(const QString &name) {
	if (name.isEmpty()
		|| name.startsWith('/')
		|| name.contains('\\')
		|| name.contains(QChar(0))
		|| name.contains(':')) {
		return true;
	}
	const auto parts = name.split('/');
	for (const auto &part : parts) {
		if (part == QStringLiteral("..")) {
			return true;
		}
	}
	return false;
}

bool PreScanZipCentralDirectory(const QByteArray &zipBytes, QString &errOut) {
	const int size = zipBytes.size();
	if (size < 22) {
		errOut = Tr("не удалось прочитать архив");
		return false;
	}
	const auto *d = reinterpret_cast<const uchar*>(zipBytes.constData());
	const int searchStart = std::max(0, size - 22 - 65535);
	int eocdPos = -1;
	for (int p = size - 22; p >= searchStart; --p) {
		if (d[p] == 0x50 && d[p + 1] == 0x4B && d[p + 2] == 0x05 && d[p + 3] == 0x06) {
			const quint16 commentLen = qFromLittleEndian<quint16>(d + p + 20);
			if (p + 22 + int(commentLen) == size) {
				eocdPos = p;
				break;
			}
		}
	}
	if (eocdPos < 0) {
		errOut = Tr("не удалось прочитать архив");
		return false;
	}
	const quint16 diskNo = qFromLittleEndian<quint16>(d + eocdPos + 4);
	const quint16 cdDiskNo = qFromLittleEndian<quint16>(d + eocdPos + 6);
	const quint16 totalEntries = qFromLittleEndian<quint16>(d + eocdPos + 10);
	const quint32 cdSize = qFromLittleEndian<quint32>(d + eocdPos + 12);
	const quint32 cdOffset = qFromLittleEndian<quint32>(d + eocdPos + 16);
	if (diskNo != 0 || cdDiskNo != 0
		|| totalEntries == 0xFFFFU || cdSize == 0xFFFFFFFFU || cdOffset == 0xFFFFFFFFU) {
		errOut = Tr("не удалось прочитать архив");
		return false;
	}
	if (quint32(totalEntries) > kRestoreMaxFiles) {
		errOut = Tr("в архиве слишком много файлов");
		return false;
	}
	if (quint64(cdOffset) + quint64(cdSize) > quint64(eocdPos)) {
		errOut = Tr("не удалось прочитать архив");
		return false;
	}

	quint64 sumUncomp = 0;
	quint64 pos = cdOffset;
	const quint64 cdEnd = quint64(cdOffset) + quint64(cdSize);
	for (quint16 idx = 0; idx < totalEntries; ++idx) {
		if (pos + 46 > cdEnd) {
			errOut = Tr("не удалось прочитать архив");
			return false;
		}
		if (d[pos] != 0x50 || d[pos + 1] != 0x4B || d[pos + 2] != 0x01 || d[pos + 3] != 0x02) {
			errOut = Tr("не удалось прочитать архив");
			return false;
		}
		const quint32 uncompSize = qFromLittleEndian<quint32>(d + pos + 24);
		const quint16 nameLen = qFromLittleEndian<quint16>(d + pos + 28);
		const quint16 extraLen = qFromLittleEndian<quint16>(d + pos + 30);
		const quint16 commentLen = qFromLittleEndian<quint16>(d + pos + 32);
		const quint32 extAttr = qFromLittleEndian<quint32>(d + pos + 38);
		if (pos + 46 + nameLen + extraLen + commentLen > cdEnd) {
			errOut = Tr("не удалось прочитать архив");
			return false;
		}
		const QByteArray rawName(reinterpret_cast<const char*>(d + pos + 46), int(nameLen));
		if (rawName.contains('\0')) {
			errOut = Tr("в архиве небезопасные пути");
			return false;
		}
		const quint32 mode = (extAttr >> 16) & 0xF000U;
		if (mode == 0xA000U) {
			errOut = Tr("в архиве небезопасные пути");
			return false;
		}
		if (IsUnsafeArchivePath(QString::fromUtf8(rawName))) {
			errOut = Tr("в архиве небезопасные пути");
			return false;
		}
		if (uncompSize > kRestoreEntryLimitBytes) {
			errOut = Tr("файл в архиве слишком большой");
			return false;
		}
		sumUncomp += uncompSize;
		if (sumUncomp > kRestoreTotalLimitBytes) {
			errOut = Tr("это не бэкап mokaGram");
			return false;
		}
		pos += 46 + nameLen + extraLen + commentLen;
	}
	return true;
}

