std::string ParseMetadataJson(const std::string &source) {
	const auto qsrc = QString::fromStdString(source);
	const auto raw = QByteArray::fromStdString(source);
	const auto parsed = AnalyzePluginSource(qsrc, raw);
	QJsonObject out;
	out.insert(QStringLiteral("meta"), parsed.meta);
	QJsonArray det;
	for (const auto &d : parsed.detected) {
		det.append(d);
	}
	out.insert(QStringLiteral("detected"), det);
	out.insert(QStringLiteral("evidence"), parsed.evidence);
	out.insert(
		QStringLiteral("error"),
		parsed.error.isEmpty() ? QJsonValue(QJsonValue::Null) : QJsonValue(parsed.error));
	out.insert(QStringLiteral("sha256"), parsed.sha256);
	return QJsonDocument(out).toJson(QJsonDocument::Compact).toStdString();
}

std::string RequestInfoJson(const std::string &encoded) {
	auto fail = []() -> std::string {
		return std::string("{\"ok\":false}");
	};
	if (encoded.size() < 8 || (encoded.size() & 1U) != 0) {
		return fail();
	}
	for (const unsigned char ch : encoded) {
		const bool hex = (ch >= '0' && ch <= '9')
			|| (ch >= 'a' && ch <= 'f')
			|| (ch >= 'A' && ch <= 'F');
		if (!hex) {
			return fail();
		}
	}
	const QByteArray raw = QByteArray::fromHex(QByteArray::fromStdString(encoded));
	if (raw.size() < 4 || (raw.size() & 3) != 0) {
		return fail();
	}
	const auto &s = GetTlSchema();
	if (!s.ready) {
		return fail();
	}
	TlReader r;
	r.data = reinterpret_cast<const uchar*>(raw.constData());
	r.size = raw.size();
	uint32_t rootCid = 0;
	if (!r.readU32(rootCid)) {
		return fail();
	}
	const int rootIdx = FindCtorIdx(s, rootCid);
	if (rootIdx < 0 || s.ctors[size_t(rootIdx)].isFunc == 0) {
		return fail();
	}
	TlVal req;
	if (!DecodeTlFields(s, r, rootIdx, 0, req) || r.pos != r.size) {
		return fail();
	}
	const QString &method = req.typeName;
	QStringList targets;
	QStringList amounts;
	WalkTlForInfo(req, method, 0, targets, amounts);

	bool sensitive = IsSensitiveTlMethod(method);
	if (!sensitive) {
		for (const auto &[k, v] : req.fields) {
			if ((k == QStringLiteral("allow_paid_stars")
					|| k == QStringLiteral("allow_paid_floodskip")
					|| k == QStringLiteral("suggested_post"))
				&& TlValTruthy(v)) {
				sensitive = true;
				break;
			}
		}
	}
	const bool allowed = !TlPermForMethod(method).isEmpty();

	QJsonObject out;
	out.insert(QStringLiteral("ok"), true);
	out.insert(QStringLiteral("method"), method);
	out.insert(QStringLiteral("sensitive"), sensitive);
	out.insert(QStringLiteral("allowed"), allowed);
	QJsonArray aArr;
	for (const auto &a : amounts) {
		aArr.append(a);
	}
	QJsonArray tArr;
	for (const auto &t : targets) {
		tArr.append(t);
	}
	out.insert(QStringLiteral("amounts"), aArr);
	out.insert(QStringLiteral("targets"), tArr);
	out.insert(QStringLiteral("sha256"), Sha256Hex(raw));
	return QJsonDocument(out).toJson(QJsonDocument::Compact).toStdString();
}

