std::string ListJson() {
	struct Row {
		QJsonObject obj;
		bool pinned = false;
	};
	std::vector<Row> rows;
	{
		std::lock_guard lock(_dataMutex);
		rows.reserve(_pluginOrder.size());
		for (const auto &pid : _pluginOrder) {
			const auto it = _plugins.find(pid);
			if (it == _plugins.end()) {
				continue;
			}
			const auto &e = it->second;
			const bool isPinned = _pinned.contains(e.id);
			QJsonObject o;
			o.insert(QStringLiteral("id"), e.id);
			o.insert(QStringLiteral("file"), e.file);
			o.insert(QStringLiteral("state"), e.state);
			o.insert(
				QStringLiteral("error"),
				e.error.isEmpty() ? QJsonValue(QJsonValue::Null) : QJsonValue(e.error));
			o.insert(QStringLiteral("enabled"), !_disabled.contains(e.id));
			o.insert(QStringLiteral("pinned"), isPinned);
			o.insert(QStringLiteral("name"), e.name.isEmpty() ? e.id : e.name);
			o.insert(QStringLiteral("description"), e.description);
			o.insert(QStringLiteral("details"), e.details);
			o.insert(QStringLiteral("has_settings"), e.hasSettings);
			o.insert(QStringLiteral("author"), e.author);
			o.insert(QStringLiteral("version"), e.version);
			o.insert(QStringLiteral("icon"), e.icon);
			o.insert(QStringLiteral("permissions"), e.permissions);
			rows.push_back({ std::move(o), isPinned });
		}
	}
	std::stable_sort(rows.begin(), rows.end(), [](const Row &a, const Row &b) {
		return a.pinned && !b.pinned;
	});
	QJsonArray arr;
	for (const auto &r : rows) {
		arr.append(r.obj);
	}
	return QJsonDocument(arr).toJson(QJsonDocument::Compact).toStdString();
}

