bool EngineEnabled() {
	return _engineEnabled.load();
}

bool SetEngineEnabled(bool enabled, LogFn log) {
	if (enabled == _engineEnabled.load()) {
		return true;
	}
	_engineEnabled.store(enabled);
	QStringList pendingLogs;
	std::vector<QString> ids;
	{
		std::lock_guard lock(_dataMutex);
		ids = _pluginOrder;
		SaveStateLocked(pendingLogs);
	}
	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}

	if (enabled) {
		const auto order = TopologicalPluginFiles(PluginsDirQ());
		QSet<QString> loadedSet;
		for (const auto &fname : order) {
			loadedSet.insert(fname);
			LoadFileImpl(fname, log, false);
		}
		std::vector<QString> remainingFiles;
		{
			std::lock_guard lock(_dataMutex);
			for (const auto &pid : _pluginOrder) {
				const auto it = _plugins.find(pid);
				if (it != _plugins.end() && !loadedSet.contains(it->second.file)) {
					remainingFiles.push_back(it->second.file);
				}
			}
		}
		const auto pdir = PluginsDirQ();
		for (const auto &fname : remainingFiles) {
			const QFileInfo fi(pdir + QStringLiteral("/") + fname);
			if (fi.isFile() && !fi.isSymLink()) {
				LoadFileImpl(fname, log, false);
			}
		}
	} else {
		for (const auto &pid : ids) {
			QString targetState = QStringLiteral("paused");
			{
				std::lock_guard lock(_dataMutex);
				if (_disabled.contains(pid)) {
					targetState = QStringLiteral("disabled");
				}
			}
			DeactivatePlugin(pid, targetState, QString());
		}
	}
	return true;
}

bool SetPinned(const std::string &id, bool pinned) {
	const auto qid = QString::fromStdString(id);
	QStringList pendingLogs;
	{
		std::lock_guard lock(_dataMutex);
		if (_plugins.find(qid) == _plugins.end()) {
			return false;
		}
		if (pinned) {
			_pinned.insert(qid);
		} else {
			_pinned.remove(qid);
		}
		SaveStateLocked(pendingLogs);
	}
	for (const auto &line : pendingLogs) {
		EmitLog(LogFn(), line);
	}
	return true;
}

bool SetEnabled(const std::string &id, bool enabled, LogFn log) {
	const auto qid = QString::fromStdString(id);
	QString fileName;
	QStringList pendingLogs;
	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(qid);
		if (it == _plugins.end()) {
			return false;
		}
		fileName = it->second.file;
		if (enabled) {
			_disabled.remove(qid);
		} else {
			_disabled.insert(qid);
		}
		SaveStateLocked(pendingLogs);
	}
	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}
	if (enabled) {
		LoadFileImpl(fileName, log, false);
	} else {
		DeactivatePlugin(qid, QStringLiteral("disabled"), QString());
	}
	return true;
}

bool Remove(const std::string &id, LogFn log) {
	const auto qid = QString::fromStdString(id);
	QString filePath;
	bool hadActive = false;
	QStringList pendingLogs;
	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(qid);
		if (it == _plugins.end()) {
			return false;
		}
		filePath = it->second.path;
		hadActive = (it->second.state == QStringLiteral("loaded")
			|| it->second.filterActive
			|| it->second.eventsActive);
		_plugins.erase(it);
		_pluginOrder.erase(
			std::remove(_pluginOrder.begin(), _pluginOrder.end(), qid),
			_pluginOrder.end());
		_disabled.remove(qid);
		_pinned.remove(qid);
		SaveStateLocked(pendingLogs);
		if (_grants.erase(qid) > 0) {
			SaveGrantsLocked(pendingLogs);
		}
	}
	if (hadActive) {
		CallBridgeJson("plugin_unloaded", QJsonObject{ { QStringLiteral("pid"), qid } });
	}
	if (!filePath.isEmpty() && QFileInfo::exists(filePath) && !QFile::remove(filePath)) {
		pendingLogs.push_back(QStringLiteral("plugins: failed to remove ") + filePath);
	}
	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}
	return true;
}

std::string CallHook(
		const std::string &name,
		const std::string &paramsJson,
		LogFn log) {
	if (name != "send_message_hook") {
		return std::string("{}");
	}
	const auto doc = QJsonDocument::fromJson(QByteArray::fromStdString(paramsJson));
	if (!doc.isObject()) {
		return std::string("{}");
	}
	QJsonObject cur = doc.object();
	const QString orig = cur.value(QStringLiteral("text")).toString();
	const QString trimmed = orig.trimmed();
	if (!trimmed.isEmpty()) {
		const QString prefix = CurrentPrefix();
		QString used;
		if (!prefix.isEmpty() && trimmed.startsWith(prefix)) {
			used = prefix;
		} else if (trimmed.startsWith('/')) {
			used = QStringLiteral("/");
		}
		if (!used.isEmpty() && used == prefix) {
			const QString after = trimmed.mid(used.size());
			int sp = 0;
			while (sp < after.size() && !after[sp].isSpace()) {
				++sp;
			}
			const QString head = after.left(sp);
			if (!head.isEmpty()) {
				const QString cmd = head.section('@', 0, 0).toLower();
				const QString rawArgs = after.mid(sp).trimmed();
				const QStringList argsList = SplitShellArgs(rawArgs);
				const QString peer = cur.value(QStringLiteral("peer")).toString();
				QString replyTo;
				const auto rtv = cur.value(QStringLiteral("reply_to"));
				if (rtv.isString()) {
					replyTo = rtv.toString();
				} else if (rtv.isDouble()) {
					replyTo = QString::number(rtv.toInteger());
				}
				if (TryRunBuiltinCommand(cmd, rawArgs, argsList, prefix, peer, replyTo, log)) {
					return std::string("{\"cancel\":true}");
				}
			}
		}
	}

	struct HookSnapshot {
		int kind = -1;
		QString word;
		QString text;
	};
	std::vector<HookSnapshot> active;
	{
		std::lock_guard lock(_dataMutex);
		for (const auto &pid : _pluginOrder) {
			const auto it = _plugins.find(pid);
			if (it == _plugins.end()) {
				continue;
			}
			const auto &e = it->second;
			if (e.state != QStringLiteral("loaded") || !e.tplEnabled) {
				continue;
			}
			if (e.tplKind == 0 || e.tplKind == 1) {
				active.push_back({ e.tplKind, e.tplWord, e.tplText });
			}
		}
	}

	bool changed = false;
	for (const auto &h : active) {
		if (h.kind == 0) {
			const QString t = cur.value(QStringLiteral("text")).toString().trimmed();
			QString w = h.word.trimmed();
			while (w.startsWith('.')) {
				w = w.mid(1);
			}
			w = w.toLower();
			QString tCmd = t;
			while (tCmd.startsWith('.')) {
				tCmd = tCmd.mid(1);
			}
			tCmd = tCmd.toLower();
			if (!w.isEmpty() && t.startsWith('.') && tCmd == w) {
				cur.insert(QStringLiteral("text"), h.text);
				changed = true;
			}
		} else if (h.kind == 1) {
			QString t = cur.value(QStringLiteral("text")).toString();
			if (!h.word.isEmpty() && t.contains(h.word)) {
				t.replace(h.word, h.text);
				cur.insert(QStringLiteral("text"), t);
				changed = true;
			}
		}
	}

	if (!changed) {
		return std::string("{}");
	}
	cur.remove(QStringLiteral("entities"));
	return QJsonDocument(QJsonObject{
		{ QStringLiteral("cancel"), false },
		{ QStringLiteral("value"), cur },
	}).toJson(QJsonDocument::Compact).toStdString();
}

