bool CallMessageFilter(const std::string &messageJson, LogFn) {
	const auto doc = QJsonDocument::fromJson(QByteArray::fromStdString(messageJson));
	if (!doc.isObject()) {
		return false;
	}
	const QString textLow = doc.object().value(QStringLiteral("text")).toString().toLower();
	if (textLow.isEmpty()) {
		return false;
	}
	std::lock_guard lock(_dataMutex);
	for (const auto &pid : _pluginOrder) {
		const auto it = _plugins.find(pid);
		if (it == _plugins.end()) {
			continue;
		}
		const auto &e = it->second;
		if (e.state != QStringLiteral("loaded")
			|| e.tplKind != 3
			|| !e.tplEnabled
			|| !HasGrantLocked(pid, QStringLiteral("messages.read"))) {
			continue;
		}
		const QString wordLow = e.tplWord.toLower();
		if (!wordLow.isEmpty() && textLow.contains(wordLow)) {
			return true;
		}
	}
	return false;
}

