void OpenPluginBuilder(LogFn) {
	const auto &tpls = BuilderTemplates();
	QJsonArray items;
	for (const auto &t : tpls) {
		items.append(Tr(t.title));
	}
	const QString cb = RegisterFwCallback([](const QJsonObject &payload) {
		if (payload.value(QStringLiteral("button")).toString() != QStringLiteral("make")) {
			return;
		}
		const auto v = payload.value(QStringLiteral("values")).toObject();
		const QString name = v.value(QStringLiteral("name")).toString().trimmed().left(40);
		const QString word = v.value(QStringLiteral("word")).toString().trimmed().left(60);
		const QString text = v.value(QStringLiteral("text")).toString().left(2000);
		int kind = v.value(QStringLiteral("kind")).toInt(0);
		kind = std::clamp(kind, 0, int(BuilderTemplates().size()) - 1);
		if (name.isEmpty() || word.isEmpty() || (kind != 3 && text.isEmpty())) {
			ShowPrivateDialog(Tr("Конструктор"), Tr("Заполните название, слово и текст."));
			return;
		}
		const QString src = BuildBuilderSource(name, kind, word, text);
		const QString dir = MakeTempSubdir(QStringLiteral("moka_builder_"));
		if (dir.isEmpty()) {
			ShowPrivateDialog(Tr("Конструктор"), Tr("не удалось записать временный файл"));
			return;
		}
		const QString path = dir + QStringLiteral("/my.plugin");
		QFile f(path);
		const QByteArray bytes = src.toUtf8();
		if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate) || f.write(bytes) != bytes.size()) {
			ShowPrivateDialog(Tr("Конструктор"), Tr("не удалось записать файл плагина"));
			return;
		}
		f.close();
		CallBridgeJson("install_plugin_file", QJsonObject{ { QStringLiteral("path"), path } });
	});

	QJsonArray fields;
	fields.append(QJsonObject{
		{ QStringLiteral("type"), QStringLiteral("input") },
		{ QStringLiteral("key"), QStringLiteral("name") },
		{ QStringLiteral("text"), Tr("Название плагина") },
		{ QStringLiteral("default"), QString() },
	});
	fields.append(QJsonObject{
		{ QStringLiteral("type"), QStringLiteral("select") },
		{ QStringLiteral("key"), QStringLiteral("kind") },
		{ QStringLiteral("text"), Tr("Шаблон") },
		{ QStringLiteral("items"), items },
		{ QStringLiteral("default"), 0 },
	});
	fields.append(QJsonObject{
		{ QStringLiteral("type"), QStringLiteral("input") },
		{ QStringLiteral("key"), QStringLiteral("word") },
		{ QStringLiteral("text"), Tr("Слово или команда") },
		{ QStringLiteral("default"), QString() },
	});
	fields.append(QJsonObject{
		{ QStringLiteral("type"), QStringLiteral("input") },
		{ QStringLiteral("key"), QStringLiteral("text") },
		{ QStringLiteral("text"), Tr("Текст") },
		{ QStringLiteral("default"), QString() },
		{ QStringLiteral("multiline"), true },
	});

	QJsonArray btns;
	btns.append(QJsonObject{
		{ QStringLiteral("id"), QStringLiteral("make") },
		{ QStringLiteral("text"), Tr("Создать") },
		{ QStringLiteral("style"), QStringLiteral("primary") },
	});
	btns.append(QJsonObject{
		{ QStringLiteral("id"), QStringLiteral("no") },
		{ QStringLiteral("text"), Tr("Отмена") },
		{ QStringLiteral("style"), QStringLiteral("cancel") },
	});

	const QString closeCb = RegisterFwCallback([cb](const QJsonObject &) {
		RemoveFwCallback(cb);
	});
	const auto dlgRes = CallBridgeJson("dialog_show", QJsonObject{
		{ QStringLiteral("pid"), QStringLiteral("_fw") },
		{ QStringLiteral("title"), Tr("Создать плагин") },
		{ QStringLiteral("message"), Tr("Без кода: выберите шаблон и заполните поля. Потом всё можно поменять в настройках плагина.") },
		{ QStringLiteral("fields"), fields },
		{ QStringLiteral("buttons"), btns },
		{ QStringLiteral("cb"), cb },
		{ QStringLiteral("close_cb"), closeCb },
	});
	if (!dlgRes.value(QStringLiteral("ok")).toBool()) {
		RemoveFwCallback(cb);
		RemoveFwCallback(closeCb);
	}
}

void RestoreBackupFile(const std::string &path, LogFn) {
	const QString qpath = QString::fromStdString(path);
	const QFileInfo qfi(qpath);
	if (!qfi.isFile() || qfi.isSymLink() || qfi.size() < 0 || quint64(qfi.size()) > kRestoreTotalLimitBytes) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("не удалось прочитать архив"));
		return;
	}
	QFile f(qpath);
	if (!f.open(QIODevice::ReadOnly)) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("не удалось прочитать архив"));
		return;
	}
	const QByteArray zipBytes = f.readAll();
	f.close();

	QString scanErr;
	if (!PreScanZipCentralDirectory(zipBytes, scanErr)) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + scanErr);
		return;
	}

	zlib::FileToRead zip(zipBytes);
	if (zip.goToFirstFile() != UNZ_OK) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("не удалось прочитать архив"));
		return;
	}

	struct ArchiveData {
		std::vector<std::pair<QString, QByteArray>> entries;
		QStringList plugins;
	};
	const auto arc = std::make_shared<ArchiveData>();
	quint64 totalBytes = 0;
	bool hasManifest = false;
	int manifestFormat = 0;
	do {
		if (arc->entries.size() >= size_t(kRestoreMaxFiles)) {
			ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("в архиве слишком много файлов"));
			return;
		}
		const QString name = zip.getCurrentFileName();
		if (IsUnsafeArchivePath(name)) {
			ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("в архиве небезопасные пути"));
			return;
		}
		QByteArray data;
		if (!name.endsWith('/')) {
			data = zip.readCurrentFileContent(int(kRestoreEntryLimitBytes));
			if (zip.error() != UNZ_OK) {
				ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("не удалось прочитать архив"));
				return;
			}
		}
		totalBytes += quint64(data.size());
		if (totalBytes > kRestoreTotalLimitBytes) {
			ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("это не бэкап mokaGram"));
			return;
		}
		if (name == QStringLiteral("manifest.json")) {
			hasManifest = true;
			const auto mdoc = QJsonDocument::fromJson(data);
			if (mdoc.isObject()) {
				manifestFormat = mdoc.object().value(QStringLiteral("format")).toInt(0);
			}
		}
		if (name.startsWith(QStringLiteral("plugins/")) && name.endsWith(QStringLiteral(".plugin"))) {
			if (data.size() > int(kPluginFileLimitBytes)) {
				ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("файл в архиве слишком большой"));
				return;
			}
			arc->plugins.push_back(name);
		}
		arc->entries.emplace_back(name, data);

		const int jump = zip.goToNextFile();
		if (jump == UNZ_END_OF_LIST_OF_FILE) {
			break;
		}
		if (jump != UNZ_OK) {
			ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("не удалось прочитать архив"));
			return;
		}
	} while (true);

	if (!hasManifest) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("это не бэкап mokaGram"));
		return;
	}
	if (manifestFormat != 1) {
		ShowPrivateDialog(Tr("Восстановление"), Tr("Файл не подходит: ") + Tr("неизвестный формат бэкапа"));
		return;
	}

	QJsonArray btns;
	btns.append(QJsonObject{
		{ QStringLiteral("id"), QStringLiteral("yes") },
		{ QStringLiteral("text"), Tr("Восстановить") },
		{ QStringLiteral("style"), QStringLiteral("red") },
	});
	btns.append(QJsonObject{
		{ QStringLiteral("id"), QStringLiteral("no") },
		{ QStringLiteral("text"), Tr("Отмена") },
		{ QStringLiteral("style"), QStringLiteral("cancel") },
	});

	ShowPrivateDialog(
		Tr("Восстановить из бэкапа?"),
		Tr("В архиве плагинов: %1. Данные плагинов, настройки, заметки, сниппеты и фильтры заменят текущие (старые файлы останутся рядом с суффиксом .bak). Плагины пройдут обычную установку с подтверждением прав.")
			.arg(arc->plugins.size()),
		btns,
		[arc](const QString &button) {
			if (button != QStringLiteral("yes")) {
				return;
			}
			const auto beginRes = CallBridgeJson("restore_stage_begin", QJsonObject());
			if (!beginRes.value(QStringLiteral("ok")).toBool()) {
				ShowPrivateDialog(
					Tr("Восстановление"),
					Tr("Не вышло: ") + beginRes.value(QStringLiteral("error")).toString());
				return;
			}
			for (const auto &[n, data] : arc->entries) {
				if (n.endsWith('/')) {
					continue;
				}
				QString stageName;
				if (n.startsWith(QStringLiteral("client/"))
					&& BackupClientFiles().contains(n.mid(7))) {
					stageName = n.mid(7);
				} else if (n.startsWith(QStringLiteral("plugin_data/"))
					&& !n.endsWith(QStringLiteral("secrets.enc"))
					&& !n.endsWith(QStringLiteral("secrets.key"))) {
					stageName = n;
				} else {
					continue;
				}
				const auto putRes = CallBridgeJson("restore_stage_put", QJsonObject{
					{ QStringLiteral("name"), stageName },
					{ QStringLiteral("data"), QString::fromLatin1(data.toBase64()) },
				});
				if (!putRes.value(QStringLiteral("ok")).toBool()) {
					ShowPrivateDialog(
						Tr("Восстановление"),
						Tr("Не вышло: ") + putRes.value(QStringLiteral("error")).toString());
					return;
				}
			}
			if (!arc->plugins.isEmpty()) {
				const QString tmpDir = MakeTempSubdir(QStringLiteral("moka_restore_"));
				if (tmpDir.isEmpty()) {
					ShowPrivateDialog(Tr("Восстановление"), Tr("Не вышло: ") + Tr("не удалось записать временный файл"));
					return;
				}
				for (const auto &n : arc->plugins) {
					const QString baseName = QFileInfo(n).fileName();
					if (baseName.isEmpty() || baseName == QStringLiteral(".") || baseName == QStringLiteral("..")) {
						continue;
					}
					QByteArray pBytes;
					for (const auto &[en, ed] : arc->entries) {
						if (en == n) {
							pBytes = ed.left(int(kPluginFileLimitBytes));
							break;
						}
					}
					const QString outPath = tmpDir + QStringLiteral("/") + baseName;
					QFile pf(outPath);
					if (!pf.open(QIODevice::WriteOnly | QIODevice::Truncate)
						|| pf.write(pBytes) != pBytes.size()) {
						ShowPrivateDialog(Tr("Восстановление"), Tr("Не вышло: ") + Tr("не удалось сохранить временный файл плагина"));
						return;
					}
					pf.close();
					CallBridgeJson("install_plugin_file", QJsonObject{ { QStringLiteral("path"), outPath } });
				}
			}
			ShowPrivateDialog(
				Tr("Восстановление"),
				Tr("Данные и настройки применятся при следующем запуске mokaGram. Плагины (%1) устанавливаются через обычное окно с правами, подтвердите каждый.")
					.arg(arc->plugins.size()));
		});
}

bool Invoke(
		const std::string &pid,
		const std::string &token,
		const std::string &payloadJson,
		LogFn) {
	if (token.empty() || pid != "_fw") {
		return false;
	}
	const QString qtok = QString::fromStdString(token);
	std::function<void(const QJsonObject&)> fn;
	{
		std::lock_guard lock(_cbMutex);
		const auto it = _fwCallbacks.find(qtok);
		if (it == _fwCallbacks.end()) {
			return false;
		}
		fn = std::move(it->second);
		_fwCallbacks.erase(it);
	}
	const auto obj = QJsonDocument::fromJson(QByteArray::fromStdString(payloadJson)).object();
	fn(obj);
	return true;
}

