void Shutdown(LogFn) {
	if (_stopping.exchange(true)) {
		return;
	}
	{
		std::lock_guard lock(_queueMutex);
	}
	_queueCv.notify_all();
	{
		std::lock_guard lock(_devMutex);
	}
	_devCv.notify_all();
	{
		std::lock_guard lock(_pingMutex);
	}
	_pingCv.notify_all();

	std::vector<QString> ids;
	{
		std::lock_guard lock(_dataMutex);
		ids = _pluginOrder;
	}
	for (const auto &pid : ids) {
		DeactivatePlugin(pid, QStringLiteral("paused"), QString());
	}

	if (_worker.joinable()) {
		_worker.join();
	}
	if (_devThread.joinable()) {
		_devThread.join();
	}
	std::vector<AuxWorker> aux;
	{
		std::lock_guard lock(_auxMutex);
		aux = std::move(_auxThreads);
		_auxThreads.clear();
	}
	for (auto &w : aux) {
		if (w.thread.joinable()) {
			w.thread.join();
		}
	}
	{
		std::lock_guard lock(_cbMutex);
		_fwCallbacks.clear();
	}
}

