void QueueHook(HookKind kind, uint32_t constructorId, const void *data, size_t sizeBytes) {
	if (!_started.load() || _stopping.load() || !data || sizeBytes == 0 || sizeBytes > kMaxHookBytes) {
		return;
	}
	if ((kind == HookKind::PreRequest || kind == HookKind::PostRequest) && IsFromPlugin()) {
		return;
	}
	HookTask task;
	task.kind = int(kind);
	task.id = constructorId;
	task.bytes = QByteArray(static_cast<const char*>(data), int(sizeBytes));
	{
		std::lock_guard lock(_queueMutex);
		if (_hookQueue.size() >= kQueueLimit) {
			return;
		}
		_hookQueue.push_back(std::move(task));
	}
	_queueCv.notify_one();
}

void QueueEvent(const std::string &name, const std::string &payloadJson) {
	if (!_started.load() || _stopping.load()) {
		return;
	}
	EventTask task;
	task.name = QString::fromStdString(name);
	task.payloadJson = QString::fromStdString(payloadJson);
	{
		std::lock_guard lock(_queueMutex);
		if (_eventQueue.size() >= kQueueLimit) {
			return;
		}
		_eventQueue.push_back(std::move(task));
	}
	_queueCv.notify_one();
}

void MarkFromPlugin(bool on) {
	if (on) {
		_fromPlugin.fetch_add(1, std::memory_order_acq_rel);
		return;
	}
	int cur = _fromPlugin.load(std::memory_order_acquire);
	while (cur > 0 && !_fromPlugin.compare_exchange_weak(cur, cur - 1, std::memory_order_acq_rel)) {
	}
}

bool IsFromPlugin() {
	return _fromPlugin.load(std::memory_order_acquire) > 0;
}

std::string RecordInstall(const std::string &fileName, LogFn log) {
	const QString qname = QString::fromStdString(fileName);
	const QString fullPath = PluginsDirQ() + QStringLiteral("/") + qname;
	const QFileInfo fi(fullPath);
	if (!fi.isFile() || fi.isSymLink() || fi.size() < 0 || fi.size() > kPluginFileLimitBytes) {
		EmitLog(log, qname + QStringLiteral(": invalid file"));
		return std::string();
	}
	QFile f(fullPath);
	if (!f.open(QIODevice::ReadOnly)) {
		EmitLog(log, qname + QStringLiteral(": ") + f.errorString());
		return std::string();
	}
	const QByteArray raw = f.readAll();
	f.close();
	const auto parsed = AnalyzePluginSource(QString::fromUtf8(raw), raw);
	const QString metaId = parsed.meta.value(QStringLiteral("__id__")).toString();
	const QString pid = metaId.isEmpty() ? qname : metaId;

	QStringList declared;
	for (const auto &v : parsed.meta.value(QStringLiteral("__permissions__")).toArray()) {
		if (v.isString()) {
			declared.push_back(v.toString());
		}
	}
	const QString digest = parsed.sha256;
	QStringList pendingLogs;
	{
		std::lock_guard lock(_dataMutex);
		_grants[pid] = GrantRecord{ digest, ComputeDefaultGrants(declared) };
		SaveGrantsLocked(pendingLogs);
	}
	EmitLog(log, Tr("[%1] установлен, хеш %2").arg(pid, digest.left(12)));
	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}
	return pid.toStdString();
}

bool Approve(const std::string &id, LogFn log) {
	const QString pid = QString::fromStdString(id);
	QString fileName;
	QString path;
	{
		std::lock_guard lock(_dataMutex);
		const auto it = _plugins.find(pid);
		if (it == _plugins.end()) {
			return false;
		}
		fileName = it->second.file;
		path = it->second.path;
	}
	const QFileInfo fi(path);
	if (!fi.isFile() || fi.isSymLink() || fi.size() < 0 || fi.size() > kPluginFileLimitBytes) {
		EmitLog(log, pid + QStringLiteral(": invalid file"));
		return false;
	}
	QFile f(path);
	if (!f.open(QIODevice::ReadOnly)) {
		EmitLog(log, pid + QStringLiteral(": ") + f.errorString());
		return false;
	}
	const QByteArray raw = f.readAll();
	f.close();
	const auto parsed = AnalyzePluginSource(QString::fromUtf8(raw), raw);
	QStringList declared;
	for (const auto &v : parsed.meta.value(QStringLiteral("__permissions__")).toArray()) {
		if (v.isString()) {
			declared.push_back(v.toString());
		}
	}
	const QString digest = parsed.sha256;
	QStringList pendingLogs;
	{
		std::lock_guard lock(_dataMutex);
		_grants[pid] = GrantRecord{ digest, ComputeDefaultGrants(declared) };
		SaveGrantsLocked(pendingLogs);
	}
	for (const auto &line : pendingLogs) {
		EmitLog(log, line);
	}
	AppendAudit(pid, digest, QStringLiteral("review"), QString(), QStringLiteral("approved"), 0);
	LoadFileImpl(fileName, log, false);
	std::lock_guard lock(_dataMutex);
	const auto it = _plugins.find(pid);
	return it != _plugins.end() && it->second.state == QStringLiteral("loaded");
}

void NotifySettingChanged(
		const std::string &key,
		const std::string &valueJson,
		LogFn) {
	const auto doc = QJsonDocument::fromJson(QByteArray::fromStdString(valueJson));
	if (!doc.isArray() || doc.array().isEmpty()) {
		return;
	}
	const QJsonValue val = doc.array().first();
	const QString qkey = QString::fromStdString(key);
	if (!qkey.startsWith(QStringLiteral("plugin."))) {
		return;
	}
	const QString rest = qkey.mid(7);
	QString targetPid;
	bool needFilterRefresh = false;
	bool filterOn = false;
	{
		std::lock_guard lock(_dataMutex);
		for (const auto &pid : _pluginOrder) {
			const QString prefix = pid + QStringLiteral(".");
			if (!rest.startsWith(prefix)) {
				continue;
			}
			const QString shortKey = rest.mid(prefix.size());
			if (shortKey != QStringLiteral("enabled")
				&& shortKey != QStringLiteral("word")
				&& shortKey != QStringLiteral("text")) {
				continue;
			}
			const auto it = _plugins.find(pid);
			if (it == _plugins.end() || it->second.state != QStringLiteral("loaded")) {
				continue;
			}
			auto &e = it->second;
			if (shortKey == QStringLiteral("enabled")) {
				e.tplEnabled = val.toBool(true);
				if (e.tplKind == 3 && HasGrantLocked(pid, QStringLiteral("messages.read"))) {
					targetPid = pid;
					needFilterRefresh = true;
					filterOn = e.tplEnabled;
					e.filterActive = filterOn;
				}
			} else if (shortKey == QStringLiteral("word")) {
				e.tplWord = val.toString();
				if (e.tplKind == 3 && HasGrantLocked(pid, QStringLiteral("messages.read"))) {
					targetPid = pid;
					needFilterRefresh = true;
					filterOn = e.tplEnabled;
					e.filterActive = filterOn;
				}
			} else if (shortKey == QStringLiteral("text")) {
				e.tplText = val.toString();
			}
			break;
		}
	}
	if (needFilterRefresh && !targetPid.isEmpty()) {
		CallBridgeJson("filter_subscribe", QJsonObject{
			{ QStringLiteral("pid"), targetPid },
			{ QStringLiteral("on"), filterOn },
		});
	}
}

